92	    /**
93	     * Country codes with a fixed national-number length. When a number's country code appears here
94	     * its national digits (everything after the code) must match exactly, otherwise it is rejected;
95	     * country codes not listed fall back to the generic 8–15 total-digit rule. '+61' (Australia)
96	     * requires 9 national digits, '+1' (NANP) requires 10.
97	     */
98	    private static final java.util.Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY =
