103	     * E.164 number (fewer than 8 or more than 15 digits after the '+', a national-number length that
104	     * is wrong for its country code, or stray non-digit characters remaining after the allowed
105	     * separators are stripped).
106	     */
107	    static String toE164(String value) {
108	        if (value == null) {
109	            return null;
110	        }
111	        String cleaned = value.replaceAll("[\\s()-]", "");
112	        String digits;
113	        if (cleaned.startsWith("+")) {
114	            digits = cleaned.substring(1);
115	        }
116	        else {
117	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
118	            digits = "61" + national;
119	        }
120	        if (!digits.matches("[0-9]{8,15}")) {
121	            return null;
122	        }
123	        if (!hasValidNationalLength(digits)) {
124	            return null;
125	        }
126	        return "+" + digits;
127	    }
128	
129	    /**
130	     * For a country code with a fixed national-number length, check the national digits (everything
131	     * after the code) match that length exactly. Unknown country codes pass (already bounded by the
132	     * generic 8–15 total-digit rule).
133	     */
134	    private static boolean hasValidNationalLength(String digits) {
135	        for (java.util.Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
136	            String code = entry.getKey();
137	            if (digits.startsWith(code)) {
138	                return digits.length() - code.length() == entry.getValue();
139	            }
140	        }
141	        return true;
142	    }
